package br.gov.dere.api; import br.gov.dere.application.access.AccessService; import br.gov.dere.persistence.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration @Profile("local") public class LocalSeedData { @Bean CommandLineRunner seed(AccessService a,DereUserRepository users,DereEntityRepository entities){return args->{if(users.count()==0){var u=a.create("admin","admin","Administrador local");var e=entities.save(new DereEntityEntity("12345678","Entidade EFPC de teste"));u.getEntities().add(e);users.save(u);}};} }
